import {surroundingPlaces} from './surroundings-data.js';
import {advanceFreeTime} from './free-roam.js';
export function surroundingsAtmosphere(s){const p=surroundingPlaces[s.location];if(!p)return '';return p.text+(s.clock.minute>=1080?' 해가 낮아지고 가로등이 하나둘 켜진다.':s.clock.minute<720?' 오전의 바람이 건물 사이로 분다.':' 햇빛과 그늘의 경계가 길 위로 길어진다.');}
export function surroundingsActions(s){const p=surroundingPlaces[s.location];if(!p)return [];return [{id:'observe',label:p.observe,minutes:10},{id:'rest',label:s.location==='riversideWalk'?'물가 길을 천천히 걸으며 쉰다.':'공공 보행 공간에서 잠깐 쉬어간다.',minutes:15}].filter(a=>s.clock.minute+a.minutes<=1320);}
export function performSurroundingsAction(state,id){const p=surroundingPlaces[state.location],a=surroundingsActions(state).find(x=>x.id===id);if(!p||!a)throw new Error('이곳에서 지금 할 수 있는 행동이 아닙니다.');let s=advanceFreeTime(state,a.minutes);s.surroundings??={};const key=`${s.day}:${state.location}:${id}`,count=s.surroundings[key]??0;s.surroundings[key]=count+1;const learned=id==='observe'&&!s.known.includes(p.fact);if(learned)s.known.push(p.fact);const text=id==='observe'?(learned?`${p.fact}를 직접 확인해 기록했다.`:count%2?'기억해 둔 방향을 반대로 걸어보며 돌아오는 길도 확인했다.':'한 번에 지나쳤던 갈림길을 다시 보고 익숙한 방향과 대조했다.'):(count%2?'서둘러 걷던 속도를 낮추고 주변 소리를 들으며 잠깐 쉬었다.':'잠깐 숨을 고르고 다음에 어디로 갈지 생각했다.');s.memory.push(`[${s.day}일차] ${p.name}: ${text}`);s.lastResult=text;s.pace={count:0,seen:{}};return s;}
